    std::println("{}", add(2, 3));
}

// Generator de números pares — usando std::generator (C++23)
#include <generator>

std::generator<int> pares(int n) {
    for (int i = 0; i < n; i += 2) {
        co_yield i;
    }
}

int main() {
    for (int x : pares(10)) std::print("{} ", x);
    // 0 2 4 6 8
}

// Pseudo-código usando lib externa (cppcoro / libunifex)
cppcoro::task<std::string> fetch(std::string url) {
    auto resp = co_await http_get(url);
    co_return resp.body;
}

cppcoro::task<int> total_bytes() {
    auto a = co_await fetch("https://a/");
    auto b = co_await fetch("https://b/");
    co_return a.size() + b.size();
}

template <typename T>
struct Task {
    struct promise_type {
        T value;
        Task get_return_object() { return {}; }
        std::suspend_never initial_suspend() { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void return_value(T v) { value = std::move(v); }
        void unhandled_exception() { std::terminate(); }
    };
};
